// Initialize global variables
light_samples = 0
diffuse_samples = 0
specular_samples = 0
refraction_samples = 0
gi_contributions = []

// For each light source
for light in lights:
    // Calculate light direction and intensity
    light_dir = normalize(light.position - eye.position)
    light_intensity = light.intensity

    // For each sample point in the light falloff
    for sample in light.falloff_samples:
        // Calculate sample position and importance
        sample_pos = light.position + sample * light.falloff_distance
        sample_importance = 1 / (sample_pos.distance_to(eye.position) ^ 2)

        // Calculate diffuse contribution
        diffuse_contrib = 0
        for material in scene.materials:
            if material.diffuse_map:
                diffuse_contrib += material.diffuse_map.at(sample_pos) * material.diffuse_color * light_intensity * sample_importance
        gi_contributions.append((light, diffuse_contrib, 0, 0))

        // Calculate specular contribution
        specular_contrib = 0
        for material in scene.materials:
            if material.specular_map:
                specular_contrib += material.specular_map.at(sample_pos) * material.specular_color * light_intensity * sample_importance
        gi_contributions.append((light, 0, specular_contrib, 0))

        // Calculate refraction contribution
        refraction_contrib = 0
        for material in scene.materials:
            if material.refraction_map:
                refraction_contrib += material.refraction_map.at(sample_pos) * material.refraction_color * light_intensity * sample_importance
        gi_contributions.append((light, 0, 0, refraction_contrib))

    // Increment sample counters
    light_samples += 1
    diffuse_samples += sum([contrib[1] for contrib in gi_contributions if contrib[1] > 0])
    specular_samples += sum([contrib[2] for contrib in gi_contributions if contrib[2] > 0])
    refraction_samples += sum([contrib[3] for contrib in gi_contributions if contrib[3] > 0])

